@startuml

class Customer {
  + Address : string
  + VATnumber : string
}

class Product {
  + Name : string
  + Stock : int
}

class Order {
  + OrderNumber : string
  + DeliveryAddress : string
  + PaidDate : date
  + ShippedDate : date
}

class OrderLine {
  + Quantity : int
  + ShippedQuantity : int
}

class Warehouse {
  + Location : string
}

class Invoice {
  + InvoiceNumber : string
}

class Shipment {
  + ShipmentNumber : string
  + Status : string
}

class Delivery {
  + DeliveryNumber : string
  + Status : string
}

Customer "1" -- "*" Order : places
Customer "1" -- "*" Warehouse : head office
Customer "1" -- "*" Warehouse : delivers to
Order "1" *-- "1..*" OrderLine
OrderLine "1" -- "1" Product
Order "1" -- "0..*" Invoice
Order "1" -- "0..*" Shipment
Shipment "1" *-- "1..*" OrderLine
Shipment "1" -- "0..*" Delivery

@enduml

